<script>
(()=>{const header=document.querySelector('.site-header');const syncHeader=()=>header?.classList.toggle('is-scrolled',scrollY>24);syncHeader();addEventListener('scroll',syncHeader,{passive:true});
const notices=[...document.querySelectorAll('.announcement div>span')];let notice=0;const showNotice=index=>{if(!notices.length)return;notices[notice].classList.remove('is-active');notice=(index+notices.length)%notices.length;notices[notice].classList.add('is-active')};document.querySelector('[data-notice-prev]')?.addEventListener('click',()=>showNotice(notice-1));document.querySelector('[data-notice-next]')?.addEventListener('click',()=>showNotice(notice+1));if(notices.length>1&&!matchMedia('(prefers-reduced-motion: reduce)').matches)setInterval(()=>showNotice(notice+1),4000);
const esc=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
const searchDrawer=document.getElementById('search-drawer'),searchInput=document.getElementById('global-search'),searchResults=document.getElementById('predictive-search');document.getElementById('open-search')?.addEventListener('click',()=>{searchDrawer.showModal();setTimeout(()=>searchInput?.focus(),50)});document.getElementById('close-search')?.addEventListener('click',()=>searchDrawer.close());searchDrawer?.addEventListener('click',event=>{if(event.target===searchDrawer)searchDrawer.close()});let searchTimer;searchInput?.addEventListener('input',()=>{clearTimeout(searchTimer);const query=searchInput.value.trim();if(query.length<2){searchResults.innerHTML='';return}searchResults.innerHTML='<p>Mencari…</p>';searchTimer=setTimeout(async()=>{try{const response=await fetch(@json(route('search.suggestions'))+'?q='+encodeURIComponent(query),{headers:{Accept:'application/json'}});const data=await response.json();searchResults.innerHTML=data.products.length?data.products.map(item=>`<a href="${esc(item.url)}"><img src="${esc(item.image)}" alt=""><span><b>${esc(item.name)}</b><small>${esc(item.price)}</small></span><i>→</i></a>`).join(''):'<p>Produk tidak ditemukan.</p>'}catch(error){searchResults.innerHTML='<p>Pencarian belum dapat dimuat.</p>'}},250)});
const cartDrawer=document.getElementById('cart-drawer'),cartLines=document.getElementById('cart-drawer-lines'),cartFooter=document.getElementById('cart-drawer-footer'),cartRecommendations=document.getElementById('cart-drawer-recommendations'),cartShipping=document.getElementById('cart-drawer-shipping');
const renderCartDrawer=data=>{cartLines.innerHTML=data.lines.length?data.lines.map(line=>`<div class="cart-drawer-line" data-drawer-line="${line.variant_id}"><a href="${esc(line.url)}"><img src="${esc(line.image)}" alt="${esc(line.name)}"></a><span><a href="${esc(line.url)}"><b>${esc(line.name)}</b></a><small>${esc(line.variant)}</small><strong>${esc(line.total)}</strong><span class="drawer-quantity"><button type="button" data-drawer-quantity="${line.quantity-1}" data-variant="${line.variant_id}" aria-label="Kurangi jumlah">−</button><span>${line.quantity}</span><button type="button" data-drawer-quantity="${line.quantity+1}" data-variant="${line.variant_id}" aria-label="Tambah jumlah">+</button><button type="button" class="drawer-remove" data-drawer-quantity="0" data-variant="${line.variant_id}">HAPUS</button></span></span></div>`).join(''):'<div class="drawer-empty"><p>Keranjang Anda masih kosong.</p><a href="{{ route('catalog') }}">MULAI BELANJA →</a></div>';cartRecommendations.innerHTML=data.recommendations?.length?`<h3>LENGKAPI PILIHAN ANDA</h3>${data.recommendations.map(item=>`<a href="${esc(item.url)}"><img src="${esc(item.image)}" alt=""><span><b>${esc(item.name)}</b><small>${esc(item.price)}</small></span><i>→</i></a>`).join('')}`:'';cartShipping.hidden=data.free_shipping_target<1;if(data.free_shipping_target>0){document.getElementById('cart-drawer-shipping-bar').style.width=data.free_shipping_progress+'%';document.getElementById('cart-drawer-shipping-copy').textContent=data.free_shipping_remaining>0?'Tambah Rp '+new Intl.NumberFormat('id-ID').format(data.free_shipping_remaining)+' lagi untuk mencapai promo gratis ongkir.':'Target promo gratis ongkir sudah tercapai.'}cartFooter.hidden=!data.lines.length;if(data.lines.length)document.getElementById('cart-drawer-subtotal').textContent=data.subtotal;const cartLink=document.querySelector('[data-open-cart]');let badge=cartLink?.querySelector('span');if(data.count>0&&!badge){badge=document.createElement('span');cartLink.append(badge)}if(badge){badge.textContent=data.count;badge.hidden=data.count<1}};
const loadCartDrawer=async()=>{cartLines.innerHTML='<p class="drawer-loading">Memuat keranjang…</p>';cartRecommendations.innerHTML='';cartFooter.hidden=true;cartShipping.hidden=true;try{const response=await fetch(@json(route('cart.summary')),{headers:{Accept:'application/json'}});renderCartDrawer(await response.json())}catch(error){cartLines.innerHTML='<p>Keranjang belum dapat dimuat. <a href="{{ route('cart') }}">Buka halaman keranjang</a>.</p>'}};
document.querySelector('[data-open-cart]')?.addEventListener('click',event=>{if(!cartDrawer?.showModal)return;event.preventDefault();cartDrawer.showModal();loadCartDrawer()});cartLines?.addEventListener('click',async event=>{const button=event.target.closest('[data-drawer-quantity]');if(!button)return;button.disabled=true;try{const response=await fetch(@json(route('cart.update')),{method:'POST',headers:{Accept:'application/json','Content-Type':'application/x-www-form-urlencoded','X-CSRF-TOKEN':@json(csrf_token())},body:new URLSearchParams({variant_id:button.dataset.variant,quantity:button.dataset.drawerQuantity})});if(!response.ok)throw new Error('cart-update-failed');renderCartDrawer(await response.json())}catch(error){button.disabled=false}});document.querySelector('[data-close-cart]')?.addEventListener('click',()=>cartDrawer.close());cartDrawer?.addEventListener('click',event=>{if(event.target===cartDrawer)cartDrawer.close()});
const quickColor=value=>{const color=String(value).toLowerCase();if(color.includes('black'))return'#202020';if(color.includes('navy'))return'#26344c';if(color.includes('olive'))return'#747452';if(color.includes('sage'))return'#a8b19a';if(color.includes('rose')||color.includes('pink'))return'#d8a7ad';if(color.includes('plum'))return'#70445d';if(color.includes('mauve'))return'#b58b96';if(color.includes('taupe'))return'#a18d7d';if(color.includes('sand')||color.includes('beige'))return'#d5c2a5';if(color.includes('ivory'))return'#f1ebdd';return'#b6aca1'};const quickDialog=document.getElementById('quick-product-dialog'),quickOptions=document.getElementById('quick-product-options'),quickVariant=document.getElementById('quick-variant'),quickSubmit=document.getElementById('quick-submit');let quickData=null,quickSelected={};const renderQuick=()=>{const kinds=[...(quickData.usesType?[['type','JENIS PRODUK']]:[]),['color','WARNA'],['size','UKURAN']];quickOptions.innerHTML=kinds.map(([kind,label])=>{const values=[...new Set(quickData.variants.map(item=>item[kind]).filter(Boolean))];return `<fieldset><legend>${label}</legend><div>${values.map(value=>{const possible=quickData.variants.some(item=>item.available>0&&item[kind]===value&&kinds.every(([other])=>other===kind||!quickSelected[other]||item[other]===quickSelected[other]));return `<button type="button" data-quick-kind="${kind}" data-quick-value="${esc(value)}" class="${quickSelected[kind]===value?'is-active':''} ${kind==='color'?'color-choice':''}" ${possible?'':'disabled'}>${kind==='color'?`<i style="--swatch:${quickColor(value)}"></i>`:''}${esc(value)}</button>`}).join('')}</div></fieldset>`}).join('');const match=quickData.variants.find(item=>item.available>0&&kinds.every(([kind])=>item[kind]===quickSelected[kind]));quickVariant.value=match?.id||'';quickSubmit.disabled=!match;document.getElementById('quick-product-price').textContent=match?new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(match.price):'Pilih opsi yang tersedia';quickOptions.querySelectorAll('[data-quick-kind]').forEach(button=>button.addEventListener('click',()=>{quickSelected[button.dataset.quickKind]=button.dataset.quickValue;renderQuick()}))};document.querySelectorAll('[data-quick-open]').forEach(button=>button.addEventListener('click',()=>{quickData=JSON.parse(document.getElementById(button.dataset.quickOpen).textContent);quickSelected={};document.getElementById('quick-product-name').textContent=quickData.name;document.getElementById('quick-product-image').src=quickData.image;document.getElementById('quick-product-image').alt=quickData.name;document.getElementById('quick-product-link').href=quickData.url;renderQuick();quickDialog.showModal()}));document.querySelector('[data-quick-close]')?.addEventListener('click',()=>quickDialog.close());quickDialog?.addEventListener('click',event=>{if(event.target===quickDialog)quickDialog.close()});
const observer='IntersectionObserver'in window?new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target)}}),{threshold:.12}):null;document.querySelectorAll('.reveal').forEach(element=>observer?observer.observe(element):element.classList.add('is-visible'));
const slides=[...document.querySelectorAll('[data-hero-slide]')],dots=[...document.querySelectorAll('[data-hero-dot]')];let active=0,timer,heroStartX=0;const show=index=>{active=(index+slides.length)%slides.length;slides.forEach((slide,i)=>{slide.classList.toggle('is-active',i===active);slide.setAttribute('aria-hidden',i===active?'false':'true')});dots.forEach((dot,i)=>dot.classList.toggle('is-active',i===active))};const autoplay=()=>{clearTimeout(timer);if(slides.length>1&&!matchMedia('(prefers-reduced-motion: reduce)').matches)timer=setTimeout(()=>{show(active+1);autoplay()},Number(slides[active]?.dataset.duration)||6500)};dots.forEach(dot=>dot.addEventListener('click',()=>{show(Number(dot.dataset.heroDot));autoplay()}));document.querySelector('[data-hero-prev]')?.addEventListener('click',()=>{show(active-1);autoplay()});document.querySelector('[data-hero-next]')?.addEventListener('click',()=>{show(active+1);autoplay()});const hero=document.querySelector('[data-hero-slider]');hero?.addEventListener('pointerdown',event=>heroStartX=event.clientX);hero?.addEventListener('pointerup',event=>{const delta=event.clientX-heroStartX;if(Math.abs(delta)>55){show(active+(delta<0?1:-1));autoplay()}});autoplay();
document.querySelectorAll('[data-drag-scroll]').forEach(track=>{let down=false,startX=0,startLeft=0;track.addEventListener('pointerdown',event=>{if(event.pointerType==='mouse'){down=true;startX=event.clientX;startLeft=track.scrollLeft;track.classList.add('is-dragging')}});addEventListener('pointerup',()=>{down=false;track.classList.remove('is-dragging')});track.addEventListener('pointermove',event=>{if(down)track.scrollLeft=startLeft-(event.clientX-startX)})});
document.querySelectorAll('.reference-carousel').forEach(shell=>{const track=shell.querySelector('.product-carousel');const move=direction=>track?.scrollBy({left:direction*(track.querySelector('.product-carousel-item')?.getBoundingClientRect().width||280),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});shell.querySelector('[data-carousel-prev]')?.addEventListener('click',()=>move(-1));shell.querySelector('[data-carousel-next]')?.addEventListener('click',()=>move(1));track?.addEventListener('scroll',()=>{const max=track.scrollWidth-track.clientWidth;shell.querySelector('[data-carousel-prev]')?.toggleAttribute('disabled',track.scrollLeft<4);shell.querySelector('[data-carousel-next]')?.toggleAttribute('disabled',track.scrollLeft>max-4)},{passive:true});shell.querySelector('[data-carousel-prev]')?.toggleAttribute('disabled',true)});
document.addEventListener('click',event=>document.querySelectorAll('.language-picker[open]').forEach(picker=>{if(!picker.contains(event.target))picker.removeAttribute('open')}));
document.querySelectorAll('[data-product-voucher-copy]').forEach(button=>button.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(button.dataset.productVoucherCopy);button.querySelector('small').textContent='KODE TERSALIN'}catch(error){button.querySelector('small').textContent=button.dataset.productVoucherCopy}}));
const socialProof=document.getElementById('social-proof'),socialProofSource=document.getElementById('social-proof-data');if(socialProof&&socialProofSource&&!sessionStorage.getItem('dthree-social-proof-dismissed')){const products=JSON.parse(socialProofSource.textContent),cities=@json($socialProofCities ?? []),interval=Math.max(10,Number(@json($shop['social_proof_interval'] ?? 24)))*1000;let proofIndex=0,proofTimer,proofHideTimer;const hideProof=()=>socialProof.classList.remove('is-visible');const showProof=()=>{clearTimeout(proofTimer);if(document.querySelector('dialog[open]')){proofTimer=setTimeout(showProof,4000);return}const product=products[proofIndex%products.length],city=cities[proofIndex%Math.max(1,cities.length)]||'Indonesia';proofIndex++;socialProof.querySelector('[data-social-proof-link]').href=product.url;socialProof.querySelector('[data-social-proof-image]').src=product.image;socialProof.querySelector('[data-social-proof-image]').alt=product.name;socialProof.querySelector('[data-social-proof-name]').textContent=product.name;socialProof.querySelector('[data-social-proof-meta]').textContent=`Pelanggan di ${city} · ${4+(proofIndex*7)%43} menit lalu`;socialProof.hidden=false;requestAnimationFrame(()=>socialProof.classList.add('is-visible'));clearTimeout(proofHideTimer);proofHideTimer=setTimeout(()=>{hideProof();proofTimer=setTimeout(showProof,interval)},6500)};proofTimer=setTimeout(showProof,7000);socialProof.querySelector('[data-social-proof-close]')?.addEventListener('click',()=>{clearTimeout(proofTimer);clearTimeout(proofHideTimer);hideProof();sessionStorage.setItem('dthree-social-proof-dismissed','1')})}
document.addEventListener('keydown',event=>{if(event.key!=='Escape')return;document.querySelectorAll('dialog[open]').forEach(dialog=>dialog.close());document.querySelector('[data-filter-panel]')?.classList.remove('is-open')});document.querySelectorAll('.mobile-nav a').forEach(link=>link.addEventListener('click',()=>bootstrap.Collapse.getInstance(document.getElementById('mobile-nav'))?.hide()));
const welcomeVoucher=document.getElementById('welcome-voucher');if(welcomeVoucher&&!localStorage.getItem('dthree-welcome-voucher')){setTimeout(()=>{welcomeVoucher.showModal();localStorage.setItem('dthree-welcome-voucher','shown')},900)}document.querySelector('[data-close-welcome]')?.addEventListener('click',()=>welcomeVoucher.close());welcomeVoucher?.addEventListener('click',event=>{if(event.target===welcomeVoucher)welcomeVoucher.close()});document.querySelector('[data-copy-voucher]')?.addEventListener('click',async event=>{await navigator.clipboard.writeText(event.currentTarget.dataset.copyVoucher);event.currentTarget.querySelector('small').textContent='KODE TERSALIN'});})();
</script>
@stack('scripts')
</body>
</html>
